package com.icaroerasmo;import com.icaroerasmo.runners.RtspRecognitionRunner;import lombok.SneakyThrows;import lombok.extern.log4j.Log4j2;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.CommandLineRunner;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.scheduling.annotation.EnableScheduling;import com.icaroerasmo.properties.FaceRecognitionProperties;@Log4j2@EnableScheduling@SpringBootApplication@EnableConfigurationProperties(FaceRecognitionProperties.class)public class JavaRtspFaceRecognition implements CommandLineRunner {    @Autowired    private RtspRecognitionRunner rtspRecognitionRunner;    public static void main(String[] args) {        SpringApplication.run(JavaRtspFaceRecognition.class, args);    }    @Override    @SneakyThrows    public void run(String... args) {        rtspRecognitionRunner.start(args);    }}